import * as Vue from "vue";

export function executeCjs(
  cjs: string | Function,
  moduleMap: Record<string, any>
) {
  const require = (id: string) => {
    if (id === "vue") return Vue;
    if (moduleMap[id]) return moduleMap[id];
    throw new Error("[executeCjs] Unavailable module: " + id);
  };
  const exports = {};
  const module = { exports };
  const fn =
    typeof cjs === "function"
      ? cjs
      : new Function("require", "exports", "module", "Vue", cjs);
  fn(require, exports, module, Vue);
  return module.exports as { default: Vue.Component };
}

export async function hydrate(js: string | Function, target: string) {
  const Component = executeCjs(js, {}).default;
  const app = Vue.createSSRApp(Component);
  registerComponents(app);
  return app.mount(target).$nextTick();
}

export function registerComponents(app: Vue.App) {
  app.component(
    "d-split",
    Vue.defineComponent({
      setup(props, { slots }) {
        return () =>
          Vue.h("div", { class: "d-split" }, [
            Vue.h("div", { class: "d-split__left" }, slots.default?.()),
            Vue.h("div", { class: "d-split__right" }, slots.right?.()),
          ]);
      },
    })
  );
}
